commands.text:
case "$GITHUB_REF" in
  refs/tags/*) ;;
  *)
    echo "::error::release.yml requires a tag ref; GITHUB_REF=${GITHUB_REF:-<empty>}."
    echo "::error::Re-run by dispatching at the tag: gh workflow run release.yml --ref vX.Y.Z"
    exit 1
    ;;
esac
TAG_NAME="$GITHUB_REF_NAME"
TAG="${TAG_NAME#v}"
PKG=$(python -c "import tomllib;print(tomllib.load(open('pyproject.toml','rb'))['project']['version'])")
NPM=$(node -p "require('./npm/package.json').version")
echo "tag=$TAG pyproject=$PKG npm=$NPM rehearse=${REHEARSE:-<empty>}"
case "$REHEARSE" in
  true)
    case "$TAG_NAME" in
      rehearse-*)
        echo "::notice::throwaway rehearsal tag $TAG_NAME; skipping version-equality (publish jobs are already skipped)."
        ;;
      *)
        [ "$TAG" = "$PKG" ] || { echo "::error::tag $TAG != pyproject $PKG"; exit 1; }
        [ "$PKG" = "$NPM" ] || { echo "::error::pyproject $PKG != npm $NPM"; exit 1; }
        ;;
    esac
    ;;
  *)
    [ "$TAG" = "$PKG" ] || { echo "::error::tag $TAG != pyproject $PKG"; exit 1; }
    [ "$PKG" = "$NPM" ] || { echo "::error::pyproject $PKG != npm $NPM"; exit 1; }
    ;;
esac
